package io.github.long0823.tclbondriver;
import java.io.*;import java.nio.charset.*;import java.nio.file.*;import java.time.*;import java.util.*;import javax.xml.parsers.*;import org.w3c.dom.*;
public final class XmlTvTest {
 static void require(boolean b,String reason){if(!b)throw new AssertionError(reason);}
 static Document xml(byte[] bytes)throws Exception{DocumentBuilderFactory f=DocumentBuilderFactory.newInstance();f.setFeature("http://apache.org/xml/features/disallow-doctype-decl",true);return f.newDocumentBuilder().parse(new ByteArrayInputStream(bytes));}
 static int crc(byte[] b,int length){int c=-1;for(int i=0;i<length;i++){c^=(b[i]&255)<<24;for(int j=0;j<8;j++)c=(c&0x80000000)!=0?(c<<1)^0x04c11db7:c<<1;}return c;}
 public static void main(String[] args)throws Exception{
  String ini="[Channel0]\nName=局 & <テスト>\nDisplayNumber=11\nONID=1234\nTSID=1234\nServiceID=101\n";IptvCatalog catalog=IptvCatalog.parse(ini.getBytes(StandardCharsets.UTF_8));long now=Instant.parse("2026-10-25T15:00:00Z").toEpochMilli();
  List<XmlTv.Programme> events=Arrays.asList(new XmlTv.Programme("1234-1234-101",now,now+3600000,"題 & <字> \"A\"\u0001😀","説明\n次の行"),new XmlTv.Programme("1234-1234-101",now,now+4000000,"重複",""),new XmlTv.Programme("other",now,now+300000,"未登録局",""),new XmlTv.Programme("1234-1234-101",now+10000,now,"不正時刻",""));
  byte[] bytes=XmlTv.build(catalog,events,now);Document doc=xml(bytes);require(doc.getElementsByTagName("channel").getLength()==1,"Channel count");require(doc.getElementsByTagName("programme").getLength()==1,"Filtering/duplicate programmes");Element p=(Element)doc.getElementsByTagName("programme").item(0);require(p.getAttribute("start").equals("20261025150000 +0000"),"Timezone");require(p.getAttribute("channel").equals("1234-1234-101"),"M3U ID mapping");require(doc.getElementsByTagName("title").item(0).getTextContent().equals("題 & <字> \"A\"😀"),"XML escaping / Unicode");
  require(catalog.playlist("http://192.0.2.1:40560",String.join("",Collections.nCopies(48,"b")),1).contains("/epg.xml\" x-tvg-url=\""),"M3U EPG link");
  TsEpg parser=new TsEpg();byte[] section=new byte[45];section[0]=0x4e;section[1]=(byte)0xb0;section[2]=42;section[3]=0;section[4]=101;section[5]=(byte)0xc1;section[8]=4;section[9]=(byte)210;section[10]=4;section[11]=(byte)210;
  ZonedDateTime time=Instant.ofEpochMilli(System.currentTimeMillis()).atZone(ZoneOffset.ofHours(9));int mjd=(int)(time.toLocalDate().toEpochDay()+40587);section[14]=0;section[15]=1;section[16]=(byte)(mjd>>8);section[17]=(byte)mjd;int[] hms={time.getHour(),time.getMinute(),time.getSecond()};for(int i=0;i<3;i++)section[18+i]=(byte)((hms[i]/10)*16+hms[i]%10);section[21]=1;section[24]=0;section[25]=15;section[26]=0x4d;section[27]=13;section[28]='j';section[29]='p';section[30]='n';section[31]=5;section[32]=0x0e;section[33]='A';section[34]='&';section[35]='B';section[36]='!';section[37]=3;section[38]=0x0e;section[39]='O';section[40]='K';int checksum=crc(section,41);for(int i=0;i<4;i++)section[41+i]=(byte)(checksum>>(24-i*8));
  byte[] packet=new byte[188];Arrays.fill(packet,(byte)255);packet[0]=0x47;packet[1]=0x40;packet[2]=18;packet[3]=0x10;packet[4]=0;System.arraycopy(section,0,packet,5,section.length);parser.feed(packet,0);require(parser.snapshot().size()==1&&parser.snapshot().get(0).title.equals("A&B!"),"EIT to ARIB title");packet[3]=0x11;packet[45]^=1;parser.feed(packet,0);require(parser.crcErrors==1,"Bad EIT CRC rejected");
  System.out.println("PASS: XMLTV IDs, UTC times, escaping, Unicode, deduplication, M3U URL, EIT/ARIB parsing and CRC rejection");
  if(args.length==2){byte[] ts=Files.readAllBytes(Paths.get(args[0]));TsEpg real=new TsEpg();for(int i=0;i+188<=ts.length;i+=188)real.feed(ts,i);System.out.println("Private TS: sections="+real.validSections+" events="+real.snapshot().size()+" crc_errors="+real.crcErrors);}
 }
}
